constexpr double C=29.9792458;
struct D{std::vector<double>v;void add(double x){if(std::isfinite(x)&&fabs(x)<10)v.push_back(x);}void p(std::string n){if(v.size()<20)return;sort(v.begin(),v.end());auto q=[&](double p){double a=p*(v.size()-1);size_t i=a;double f=a-i;return v[i]*(1-f)+v[std::min(i+1,v.size()-1)]*f;};double med=q(.5);long long t1=0,t5=0;for(double x:v){if(fabs(x-med)>.5)t1++;if(fabs(x-med)>1)t5++;}std::cout<<n<<" n="<<v.size()<<" med="<<med<<" sig68="<<(q(.84)-q(.16))/2<<" q95abs=";std::vector<double>a;for(double x:v)a.push_back(fabs(x));sort(a.begin(),a.end());std::cout<<a[(size_t)(.95*(a.size()-1))]<<" tail.5="<<(double)t1/v.size()<<" tail1="<<(double)t5/v.size()<<"\n";}};
void qlin(double beta,const double seg[4],double q[4]){q[0]=0;double ib=1/beta;for(int i=1;i<4;i++)q[i]=q[i-1]+seg[i]*ib/C;}
bool qnl(double beta,double zeta,double mass,const float ed[4],const double seg[4],double q[4]){q[0]=0;if(beta>=1-1e-10){qlin(beta,seg,q);return true;}double E=mass/sqrt(1-beta*beta),Eup=E+zeta*ed[1]*1e-3,Edn=E-zeta*ed[2]*1e-3;if(!(Eup>mass&&Edn>mass))return false;double ibu=1/sqrt(1-mass*mass/Eup/Eup),ibd=1/sqrt(1-mass*mass/Edn/Edn);q[1]=0;q[2]=seg[2]/beta/C;q[0]=-seg[1]*ibu/C;q[3]=q[2]+seg[3]*ibd/C;return true;}
double pred(double beta,bool nl,int hide,double zeta,double mass,const float ed[4],const double seg[4],const float t[4]){double q[4];if(nl){if(!qnl(beta,zeta,mass,ed,seg,q))return NAN;}else qlin(beta,seg,q);double a=0;int n=0;for(int i=0;i<4;i++)if(i!=hide){a+=t[i]-q[i];n++;}return a/n+q[hide];}
double fitlin(int hide,const double s[4],const float t[4]){double ms=0,mt=0;int n=0;for(int i=0;i<4;i++)if(i!=hide){ms+=s[i];mt+=t[i];n++;}ms/=n;mt/=n;double num=0,den=0;for(int i=0;i<4;i++)if(i!=hide){num+=(s[i]-ms)*(t[i]-mt);den+=(s[i]-ms)*(s[i]-ms);}double ib=C*num/den;ib=std::max(.6,std::min(10.,ib));return 1/ib;}
int main(){const char*fn="/lustre02/user/yachen/public/amsd69n_B1130_Data_TofCalibN2/1306976244_0.root";TFile f(fn);auto t=(TTree*)f.Get("amstreea");float tl[4],ed[4],leng[4],tkq[2],tkqin[2][3],bl;int qs;t->SetBranchStatus("*",0);for(auto b:{"tof_tl","tof_edep","tof_leng","tk_q","tk_qin","tof_betah","tof_qs"})t->SetBranchStatus(b,1);t->SetBranchAddress("tof_tl",tl);t->SetBranchAddress("tof_edep",ed);t->SetBranchAddress("tof_leng",leng);t->SetBranchAddress("tk_q",tkq);t->SetBranchAddress("tk_qin",tkqin);t->SetBranchAddress("tof_betah",&bl);t->SetBranchAddress("tof_qs",&qs);std::map<std::string,D>L,N;long long ev=0,fail=0;for(Long64_t e=0;e<t->GetEntries();e++){t->GetEntry(e);if(!(bl>.4&&bl<.9&&qs==1111))continue;bool ok=1;for(int i=0;i<4;i++)if(tl[i]==-1||ed[i]<=0)ok=0;if(!ok)continue;double seg[4]={0,leng[1]-leng[0],leng[2]-leng[1],leng[3]-leng[2]},s[4]={0,seg[1],seg[1]+seg[2],seg[1]+seg[2]+seg[3]};if(!(seg[1]>0&&seg[2]>0&&seg[3]>0))continue;int Z=(int)(((tkqin[0][2]<2.5)?tkq[1]:tkqin[0][2])+.5);if(Z!=2&&Z!=6&&Z!=8)continue;double zeta=Z==2?3.258719208:Z==6?2.838085203:2.601233755;double mass=2*Z*.9314941;ev++;std::string bb=bl<.6?"b.4-.6":bl<.7?"b.6-.7":bl<.8?"b.7-.8":"b.8-.9";/* Center mode initializes its offset from S1 and S4, so only S2/S3 are valid holdouts. */for(int h=1;h<3;h++){float th[4];for(int i=0;i<4;i++)th[i]=tl[i];th[h]=-1;float er[4]={.1544809,.1544809,.1544809,.1544809};double bn=BetaNL(BetaNLPars(bl,mass,ed,th,er,leng),zeta,EnergyLossScaleMode::All,BetaReferencePoint::AMSCenter).Beta();double bll=fitlin(h,s,tl);double pl=pred(bll,0,h,zeta,mass,ed,seg,tl),pn=pred(bn,1,h,zeta,mass,ed,seg,tl);if(!std::isfinite(pn)){fail++;continue;}L["all"].add(pl-tl[h]);N["all"].add(pn-tl[h]);L[bb].add(pl-tl[h]);N[bb].add(pn-tl[h]);}}
std::cout<<"events="<<ev<<" fail="<<fail<<"\n";for(auto&x:L){x.second.p("L_"+x.first);N[x.first].p("N_"+x.first);} }
